-- [Customer_primary_key] primaryKey: customer_id identifies each Customer: never null, never repeated.
WITH focus AS (
  SELECT customer_id AS `customer_id`
  FROM `sqlgen-testing.shop.customers`
),
stats AS (
  SELECT
    COUNT(*) AS total,
    COUNTIF(`customer_id` IS NULL) AS null_keys,
    COUNT(DISTINCT IF(`customer_id` IS NOT NULL, CAST(`customer_id` AS STRING), NULL)) AS distinct_keys
  FROM focus
),
repeated AS (
  SELECT TO_JSON_STRING(ARRAY_AGG(STRUCT(kcmd_value AS value, kcmd_n AS count) ORDER BY kcmd_n DESC, kcmd_value LIMIT 5)) AS top_repeated
  FROM (
    SELECT CAST(`customer_id` AS STRING) AS kcmd_value, COUNT(*) AS kcmd_n
    FROM focus
    WHERE `customer_id` IS NOT NULL
    GROUP BY kcmd_value
    HAVING kcmd_n > 1
  )
)
SELECT *
FROM stats CROSS JOIN repeated;

