-- [Invoice_primary_key] primaryKey: (invoice_id, revision) identifies each Invoice: never null, never repeated.
WITH focus AS (
  SELECT invoice_id AS `invoice_id`, revision AS `revision`
  FROM `sqlgen-testing.shop.invoices`
),
stats AS (
  SELECT
    COUNT(*) AS total,
    COUNTIF(`invoice_id` IS NULL OR `revision` IS NULL) AS null_keys,
    COUNT(DISTINCT IF(`invoice_id` IS NOT NULL AND `revision` IS NOT NULL, TO_JSON_STRING([CAST(`invoice_id` AS STRING), CAST(`revision` AS STRING)]), NULL)) AS distinct_keys
  FROM focus
),
repeated AS (
  SELECT TO_JSON_STRING(ARRAY_AGG(STRUCT(kcmd_value AS value, kcmd_n AS count) ORDER BY kcmd_n DESC, kcmd_value LIMIT 5)) AS top_repeated
  FROM (
    SELECT TO_JSON_STRING([CAST(`invoice_id` AS STRING), CAST(`revision` AS STRING)]) AS kcmd_value, COUNT(*) AS kcmd_n
    FROM focus
    WHERE `invoice_id` IS NOT NULL AND `revision` IS NOT NULL
    GROUP BY kcmd_value
    HAVING kcmd_n > 1
  )
)
SELECT *
FROM stats CROSS JOIN repeated;

-- [placedBy_cardinality] cardinality: Each Order has at most one Customer through placedBy (many-to-one).
-- [placedBy_orphans] orphans: Every Order.customer_id that is set matches a row of Customer (placedBy).
WITH src AS (
  SELECT order_id AS `order_id`, customer_id AS `customer_id`
  FROM `sqlgen-testing.shop.orders`
),
dst AS (
  SELECT `customer_id` AS kcmd_j0, COUNT(*) AS kcmd_n
  FROM (
    SELECT customer_id AS `customer_id`
    FROM `sqlgen-testing.shop.customers`
  )
  WHERE `customer_id` IS NOT NULL
  GROUP BY kcmd_j0
),
joined AS (
  SELECT src.*, IFNULL(dst.kcmd_n, 0) AS kcmd_targets
  FROM src
  LEFT JOIN dst ON src.`customer_id` = dst.kcmd_j0
),
stats AS (
  SELECT
    COUNT(*) AS total,
    COUNTIF(`customer_id` IS NOT NULL) AS fk_rows,
    COUNTIF(`customer_id` IS NOT NULL AND kcmd_targets = 0) AS orphan_rows,
    COUNT(DISTINCT IF(`customer_id` IS NOT NULL AND kcmd_targets = 0, CAST(`customer_id` AS STRING), NULL)) AS orphan_values,
    COUNTIF(kcmd_targets > 1) AS fanout_rows,
    IFNULL(MAX(kcmd_targets), 0) AS max_targets
  FROM joined
),
sources AS (
  SELECT IFNULL(MAX(kcmd_n), 0) AS max_sources
  FROM (
    SELECT COUNT(*) AS kcmd_n
    FROM joined
    WHERE kcmd_targets > 0
    GROUP BY CAST(`customer_id` AS STRING)
  )
),
orphans AS (
  SELECT TO_JSON_STRING(ARRAY_AGG(STRUCT(kcmd_value AS value, kcmd_n AS count) ORDER BY kcmd_n DESC, kcmd_value LIMIT 5)) AS top_orphans
  FROM (
    SELECT CAST(`customer_id` AS STRING) AS kcmd_value, COUNT(*) AS kcmd_n
    FROM joined
    WHERE `customer_id` IS NOT NULL AND kcmd_targets = 0
    GROUP BY kcmd_value
  )
)
SELECT *
FROM stats CROSS JOIN sources CROSS JOIN orphans;

