-- [Customer_credit_limit_regime] regimeShift: Customer.credit_limit keeps one scale over time (by Customer.signup_date).
WITH focus AS (
  SELECT
    SAFE_CAST(signup_date AS DATE) AS kcmd_time,
    SAFE_CAST(credit_limit AS FLOAT64) AS kcmd_v0
  FROM `sqlgen-testing.shop.customers`
),
windows AS (
  SELECT
    DIV(EXTRACT(YEAR FROM kcmd_time) * 12 + EXTRACT(MONTH FROM kcmd_time) - 1, 3) AS kcmd_window,
    COUNT(NULLIF(kcmd_v0, 0)) AS n0,
    APPROX_QUANTILES(ABS(NULLIF(kcmd_v0, 0)), 2)[SAFE_OFFSET(1)] AS m0
  FROM focus
  WHERE kcmd_time IS NOT NULL
  GROUP BY kcmd_window
)
SELECT TO_JSON_STRING(ARRAY_AGG(STRUCT(kcmd_window AS w, n0, m0) ORDER BY kcmd_window)) AS series
FROM windows;

-- [Order_total_regime] regimeShift: Order.total keeps one scale over time (by Order.order_date).
-- [Order_discount_regime] regimeShift: Order.discount keeps one scale over time (by Order.order_date).
-- [Order_quantity_regime] regimeShift: Order.quantity keeps one scale over time (by Order.order_date).
WITH focus AS (
  SELECT
    SAFE_CAST(order_date AS DATE) AS kcmd_time,
    SAFE_CAST(total AS FLOAT64) AS kcmd_v0,
    SAFE_CAST(discount_cents AS FLOAT64) AS kcmd_v1,
    SAFE_CAST(quantity AS FLOAT64) AS kcmd_v2
  FROM `sqlgen-testing.shop.orders`
),
windows AS (
  SELECT
    DIV(EXTRACT(YEAR FROM kcmd_time) * 12 + EXTRACT(MONTH FROM kcmd_time) - 1, 3) AS kcmd_window,
    COUNT(NULLIF(kcmd_v0, 0)) AS n0,
    APPROX_QUANTILES(ABS(NULLIF(kcmd_v0, 0)), 2)[SAFE_OFFSET(1)] AS m0,
    COUNT(NULLIF(kcmd_v1, 0)) AS n1,
    APPROX_QUANTILES(ABS(NULLIF(kcmd_v1, 0)), 2)[SAFE_OFFSET(1)] AS m1,
    COUNT(NULLIF(kcmd_v2, 0)) AS n2,
    APPROX_QUANTILES(ABS(NULLIF(kcmd_v2, 0)), 2)[SAFE_OFFSET(1)] AS m2
  FROM focus
  WHERE kcmd_time IS NOT NULL
  GROUP BY kcmd_window
)
SELECT TO_JSON_STRING(ARRAY_AGG(STRUCT(kcmd_window AS w, n0, m0, n1, m1, n2, m2) ORDER BY kcmd_window)) AS series
FROM windows;

