-- [VipCustomer_email_required] requiredNulls: Every VipCustomer has a value for VipCustomer.email.
WITH focus AS (
  SELECT customer_id AS `customer_id`, email AS `email`
  FROM `sqlgen-testing.shop.customers`
  WHERE (COALESCE(credit_limit >= 10000, FALSE))
)
SELECT
  COUNT(*) AS total,
  COUNTIF(`email` IS NULL) AS nulls_0
FROM focus;

