-- [Order_order_date_some] requiredNulls: Every Order has a value for Order.order_date.
WITH focus AS (
  SELECT order_id AS `order_id`, status AS `status`, order_date AS `order_date`
  FROM `sqlgen-testing.shop.orders`
)
